{"file_path":"tests/test_spec.py","content":""""Behavioral checks for every section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_is_unflagged_and_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0
    assert isinstance(monitor_flag_rate([]), float)


def test_section_2_weighted_and_empty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event(str(i), 1, False) for i in range(3)], "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (4, 10), (9, 10)])
def test_section_3_window(days, expected):
    assert flags_in_window([1, 2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_section_4_flags_whitespace_and_skipped_lines():
    lines = ["  # comment,not,a,record", "", "  \t ", " x ,  3 , 1 ",
             "y, -2, 0", "z,0,   "]
    assert parse_transcript_log(lines) == [event("x", 3, True),
                                          event("y", -2, False),
                                          event("z", 0, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,notaday,1", "a,1,no"])
def test_section_4_errors_report_input_line_including_skipped(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["# comment", " ", bad_line])


def test_section_5_duplicate_ids_keep_last_then_sort_by_day_and_id():
    events = [event("b", 1, True), event("a", 3, True), event("c", 1, False),
              event("b", 2, None), event("a", 1, False)]
    assert dedupe_transcripts(events) == [events[4], events[2], events[3]]
    assert dedupe_transcripts([]) == []


def test_section_6_inclusive_calendar_range_and_empty_days():
    events = [event("a", 1, True), event("b", 2, None), event("c", 3, True),
              event("d", 3, True), event("e", 4, False), event("f", 5, True)]
    assert daily_flag_counts(events, 2, 4) == [0, 2, 0]
    assert daily_flag_counts([], 2, 4) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 3) == [2]
    assert daily_flag_counts(events, 4, 3) == []


def test_section_7_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"empty": [], "a": [event("a", 1, True)],
              "b": [event("b", 2, True), event("c", 5, False),
                    event("d", 5, False), event("e", 5, False),
                    event("f", 5, False)]}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_ranking_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("a", 1, True)],
              "c": [event("c", 1, None)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b", "c"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 1) == []


def test_section_9_all_groups_in_sorted_key_order_empty_is_none():
    groups = {"z": [], "c": [event("c", 1, None)],
              "a": [event("a", 1, True), event("b", 1, False)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "c", "z"]
    assert result == {"a": 0.5, "c": 0.0, "z": None}
    assert flag_rate_by_group({}) == {}


def test_section_10_streak_uses_strictly_positive_consecutive_entries():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6, 0]) == 3
    assert longest_flag_streak([1, 0, 1]) == 1
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
